// GLSL Fragment Shader
#version 330 core
in vec3 fragNormal;
out vec4 color;
void main() {
    vec3 lightDir = normalize(vec3(1, 1, 1));
    float diff = max(dot(normalize(fragNormal), lightDir), 0.0);
    color = vec4(vec3(diff), 1.0);
}

