3D Audio (Positional Audio):
function update3DAudio(listenerPos, sourcePos, source) {
    const dx = sourcePos.x - listenerPos.x;
    const dy = sourcePos.y - listenerPos.y;
    const dz = sourcePos.z - listenerPos.z;
    const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);

    // Inverse square law attenuation
    const volume = Math.min(1, 1 / (dist * dist));
    source.setVolume(volume);

    // Simple pan: left/right based on angle
    const angle = Math.atan2(dx, dz);
    source.setPan(Math.sin(angle));
}

DSP Effects:
function createReverb(ctx, duration = 2) {
    const convolver = ctx.createConvolver();
    const sampleRate = ctx.sampleRate;
    const length = sampleRate * duration;
    const impulse = ctx.createBuffer(2, length, sampleRate);
    for (let ch = 0; ch < 2; ch++) {
        const data = impulse.getChannelData(ch);
        for (let i = 0; i < length; i++) {
            data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (sampleRate * 0.3));
        }
    }
    convolver.buffer = impulse;
    return convolver;
}

