Quaternions:
class Quaternion {
    constructor(w, x, y, z) { this.w = w; this.x = x; this.y = y; this.z = z; }
    static fromAxisAngle(axis, angle) {
        const half = angle / 2, s = Math.sin(half);
        return new Quaternion(Math.cos(half), axis.x * s, axis.y * s, axis.z * s);
    }
    mul(q) {
        return new Quaternion(
            this.w*q.w - this.x*q.x - this.y*q.y - this.z*q.z,
            this.w*q.x + this.x*q.w + this.y*q.z - this.z*q.y,
            this.w*q.y - this.x*q.z + this.y*q.w + this.z*q.x,
            this.w*q.z + this.x*q.y - this.y*q.x + this.z*q.w
        );
    }
    rotate(v) {
        const p = new Quaternion(0, v.x, v.y, v.z);
        const qinv = new Quaternion(this.w, -this.x, -this.y, -this.z);
        const r = this.mul(p).mul(qinv);
        return { x: r.x, y: r.y, z: r.z };
    }
}

Interpolation (Lerp, Slerp, Easing):
function lerp(a, b, t) { return a + (b - a) * t; }
function slerp(qa, qb, t) {
    let cosHalfTheta = qa.w*qb.w + qa.x*qb.x + qa.y*qb.y + qa.z*qb.z;
    if (cosHalfTheta < 0) { qb = qb.negate(); cosHalfTheta = -cosHalfTheta; }
    const theta = Math.acos(cosHalfTheta);
    const sinHalfTheta = Math.sin(theta);
    const ra = Math.sin((1 - t) * theta) / sinHalfTheta;
    const rb = Math.sin(t * theta) / sinHalfTheta;
    return qa.scale(ra).add(qb.scale(rb));
}
function easeOutBounce(t) {
    if (t < 1/2.75) return 7.5625*t*t;
    else if (t < 2/2.75) { t -= 1.5/2.75; return 7.5625*t*t + 0.75; }
    else if (t < 2.5/2.75) { t -= 2.25/2.75; return 7.5625*t*t + 0.9375; }
    else { t -= 2.625/2.75; return 7.5625*t*t + 0.984375; }
}

Noise Functions:
function perlinNoise(x, y) {
    // Simplified 2D Perlin
    const xi = Math.floor(x) & 255, yi = Math.floor(y) & 255;
    const xf = x - Math.floor(x), yf = y - Math.floor(y);
    const u = xf * xf * (3 - 2 * xf);
    const v = yf * yf * (3 - 2 * yf);
    const aa = p[p[xi] + yi], ab = p[p[xi] + yi + 1];
    const ba = p[p[xi + 1] + yi], bb = p[p[xi + 1] + yi + 1];
    return lerp(lerp(grad(aa, xf, yf), grad(ba, xf - 1, yf), u),
                lerp(grad(ab, xf, yf - 1), grad(bb, xf - 1, yf - 1), u), v);
}
function fbm(x, y, octaves = 6) {
    let value = 0, amplitude = 1, frequency = 1, max = 0;
    for (let i = 0; i < octaves; i++) {
        value += amplitude * perlinNoise(x * frequency, y * frequency);
        max += amplitude;
        amplitude *= 0.5;
        frequency *= 2;
    }
    return value / max;
}

