function worldToScreen(worldPos, viewMatrix, projMatrix, viewport) {
    let clip = projMatrix.mul(viewMatrix).mul(new Vec4(worldPos.x, worldPos.y, worldPos.z, 1));
    // Perspective divide
    let ndc = new Vec3(clip.x / clip.w, clip.y / clip.w, clip.z / clip.w);
    // Viewport transform
    return {
        x: (ndc.x * 0.5 + 0.5) * viewport.width,
        y: (1 - (ndc.y * 0.5 + 0.5)) * viewport.height,
        depth: ndc.z
    };
}

