function considerAttack(agent) {
    const distanceScore = 1 - (agent.distToEnemy / 100); // closer = higher
    const healthScore = agent.health / 100;
    const ammoScore = agent.ammo / 30;

    // Combine with response curve
    const attackScore = distanceScore * healthScore * Math.min(1, ammoScore);
