    return attackScore > fleeScore ? 'ATTACK' : 'FLEE';
}

A* Pathfinding:
function aStar(start, goal, graph) {
    const open = new MinHeap();
    open.push(start, 0);
    const cameFrom = new Map();
    const gScore = new Map();
    gScore.set(start, 0);

    while (!open.isEmpty()) {
        const current = open.pop();
        if (current === goal) return reconstruct(cameFrom, current);
        for (const [neighbor, cost] of graph.neighbors(current)) {
            const tentativeG = gScore.get(current) + cost;
            if (tentativeG < (gScore.get(neighbor) ?? Infinity)) {
                cameFrom.set(neighbor, current);
                gScore.set(neighbor, tentativeG);
                const f = tentativeG + heuristic(neighbor, goal);
                open.push(neighbor, f);
            }
        }
    }
    return null;
}

Dijkstra & JPS Pathfinding:
function jump(grid, current, direction) {
    // Jump Point Search pruning
    const next = { x: current.x + direction.x, y: current.y + direction.y };
    if (!grid.isWalkable(next)) return null;
    if (next === goal) return next;

    // Check forced neighbors
    if (direction.x !== 0 && direction.y !== 0) {
        // Diagonal: check horizontal/vertical forced neighbors
        if (!grid.isWalkable({x: next.x - direction.x, y: next.y}) &&
             grid.isWalkable({x: next.x - direction.x, y: next.y + direction.y}))
            return next;
    }
    return jump(grid, next, direction);
}

