function flocking(boid, neighbors) {
    let separation = {x:0,y:0}, alignment = {x:0,y:0}, cohesion = {x:0,y:0};
    for (const other of neighbors) {
        const dx = boid.x - other.x, dy = boid.y - other.y;
        const dist = Math.sqrt(dx*dx + dy*dy);
        if (dist < sepRadius) {
            separation.x += dx / dist;
            separation.y += dy / dist;
        }
        alignment.x += other.vx;
        alignment.y += other.vy;
        cohesion.x += other.x;
        cohesion.y += other.y;
    }
    const n = neighbors.length;
    alignment = {x: alignment.x/n - boid.vx, y: alignment.y/n - boid.vy};
    cohesion = {x: cohesion.x/n - boid.x, y: cohesion.y/n - boid.y};

    boid.vx += separation.x * 1.5 + alignment.x * 1 + cohesion.x * 0.5;
    boid.vy += separation.y * 1.5 + alignment.y * 1 + cohesion.y * 0.5;
}

