function twoBoneIK(a, b, c, target) {
    // a: shoulder, b: elbow, c: hand, target: desired position
    const lab = dist(a, b), lbc = dist(b, c);
    const lat = Math.min(lab + lbc - 0.01, dist(a, target));

    // Law of cosines for elbow angle
    const cosB = (lab*lab + lbc*lbc - lat*lat) / (2 * lab * lbc);
    const angleB = Math.acos(Math.max(-1, Math.min(1, cosB)));

    // Rotate b towards target
    const dirAtoT = normalize(sub(target, a));
    b = add(a, scale(dirAtoT, lab));
    c = add(b, scale(rotate(dirAtoT, angleB), lbc));
    return { b, c };
}

