using Cinemachine;

public class CameraManager : MonoBehaviour {
    [SerializeField] private CinemachineVirtualCamera[] vCams;
    private int activeCam = 0;

    public void SwitchCamera(int index) {
        // Cinemachine handles blending automatically
        vCams[activeCam].Priority = 0;
        vCams[index].Priority = 1;
        activeCam = index;
    }

    public void ShakeCamera(float intensity, float duration) {
        var noise = vCams[activeCam].GetCinemachineComponent<CinemachineBasicMultiChannelPerlin>();
        noise.m_AmplitudeGain = intensity;
        Invoke(() => noise.m_AmplitudeGain = 0, duration);
    }
}

Burst Compiler & Jobs System:
using Unity.Burst;
using Unity.Jobs;
using Unity.Collections;

[BurstCompile]
struct UpdatePositionsJob : IJobParallelFor {
    public NativeArray<Vector3> positions;
    public NativeArray<Vector3> velocities;
    public float deltaTime;

    public void Execute(int i) {
        positions[i] += velocities[i] * deltaTime;
        // Simple bounce off floor
        if (positions[i].y < 0) {
            positions[i].y = 0;
            velocities[i].y *= -0.5f;
        }
    }
}

void Update() {
    var job = new UpdatePositionsJob {
        positions = positionsArray,
        velocities = velocitiesArray,
        deltaTime = Time.deltaTime
    };
    JobHandle handle = job.Schedule(positionsArray.Length, 64);
    handle.Complete();
}

