    void Update() {
        Profiler.BeginSample("SpawnProjectiles");
        SpawnProjectiles();
        Profiler.EndSample();

        // Use profiler markers in play mode
        // Check Stats window: Batches, SetPass calls, Triangles
        // Use Frame Debugger to see each draw call
